-- ===== supabase/updates/20261203000500_fast_rank_time.sql =====
-- ===== idempotent copy of migrations/20261203000500_fast_rank_time.sql =====
-- (the migration itself is written idempotently; keep both files identical below this line)
-- =============================================================================
-- NEXA · 0500 · Time in a rank runs fast: one paid hour counts as a day (ADR-118)
-- =============================================================================
-- "12 Stunden im Rang gearbeitet" took a day and a half of real time. Game time is fast everywhere else, so the
-- hours in a rank now count careers.promotion.rankHoursPerRealHour times (24: one paid real hour is a whole day).
-- player_jobs.rank_minutes keeps counting paid real minutes; the factor is applied where hours are compared
-- (here) and where they are shown (client). Without the config key the factor is 1.
-- Idempotent: runs unchanged as supabase/updates/20261203000500_fast_rank_time.sql.

create or replace function public.promotion_requirements(p_next text, p_level integer, p_scores jsonb, p_main text,
                                                         p_rank_minutes bigint)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  with c as (
    select public.promotion_cfg() as p,
           public.career_tier_min_score(p_next) as score,
           coalesce((select floor(public.cfg_num(t, '{minLevel}', 1))::integer
                       from jsonb_array_elements(public.career_tiers()) t where t ->> 'id' = p_next limit 1), 1) as min_level
  ), r as (
    select 1 as ord, 'level' as key, null::text as branch, c.min_level as need, coalesce(p_level, 0) as have from c
    union all
    select 2, 'branch', p_main, c.score, coalesce((p_scores ->> p_main)::integer, 0) from c
    union all
    select 3, 'management', 'management', c.score / 2, coalesce((p_scores ->> 'management')::integer, 0) from c
     where coalesce(c.p -> 'managementFrom', '[]'::jsonb) ? p_next and p_main is distinct from 'management'
    union all
    -- hours in the rank: paid minutes times rankHoursPerRealHour (ADR-118), whole hours against the hours of the rank
    select 4, 'hours', null, ceil(public.cfg_num(c.p, array['hoursByTier', p_next], 0))::integer,
           floor(greatest(0, coalesce(p_rank_minutes, 0))
                 * greatest(1, public.cfg_num(c.p, '{rankHoursPerRealHour}', 1)) / 60)::integer from c
  )
  select coalesce(jsonb_agg(jsonb_build_object('key', r.key, 'branch', r.branch, 'need', r.need, 'have', r.have,
                                               'met', r.have >= r.need) order by r.ord), '[]'::jsonb)
    from r;
$$;

-- ===== supabase/updates/20261203000600_stock_news.sql =====
-- ===== idempotent copy of migrations/20261203000600_stock_news.sql =====
-- (the migration itself is written idempotently; keep both files identical below this line)
-- =============================================================================
-- NEXA · 0600 · Stock news with a lead: hints that announce a price move (ADR-119)
-- =============================================================================
-- Every few minutes one listed stock gets a news item that points up or down ("Analysten erwarten ..."). After a
-- lead time the move happens (event_price_shock, as for announced events), or the hint fizzles: most hints come
-- true, not all. Players who read the news can position themselves before the move.
--
-- stock_tips (internal, no client rights): the hidden plan per hint.
-- stock_news_run_due(p_now) (internal, cron every minute): settles due hints, publishes a new one when it is time.
-- get_stock_news(p_limit) (authenticated) -> {"items": [STOCK_NEWS], "reliability_bps"}
--   STOCK_NEWS = {"id", "ticker", "name", "headline", "body", "direction": "up"|"down", "strength": 1..3,
--                 "published_at", "due_at", "status": "open"|"confirmed"|"fizzled", "move_bps": integer|null}
--   move_bps is only told once a hint is settled.
-- Values: game_config.stockNews (everyMinutes, leadMinMinutes, leadMaxMinutes, minMoveBps, maxMoveBps,
-- reliabilityBps, keepHours); enabled only while the key exists, so older configs publish nothing.
-- Idempotent: runs unchanged as supabase/updates/20261203000600_stock_news.sql.

create table if not exists public.stock_tips (
  id            bigint generated always as identity primary key,
  security_id   uuid not null references public.securities (id) on delete cascade,
  news_item_id  bigint references public.news_items (id) on delete set null,
  result_news_id bigint references public.news_items (id) on delete set null,
  direction     smallint not null check (direction in (-1, 1)),
  move_bps      integer not null check (move_bps > 0),
  strength      smallint not null check (strength between 1 and 3),
  comes_true    boolean not null,
  headline      text not null,
  body          text not null,
  published_at  timestamptz not null default now(),
  due_at        timestamptz not null,
  applied_at    timestamptz
);
alter table public.stock_tips enable row level security;
create index if not exists stock_tips_published_idx on public.stock_tips (published_at desc);
create index if not exists stock_tips_open_idx on public.stock_tips (due_at) where applied_at is null;
create index if not exists stock_tips_security_idx on public.stock_tips (security_id);
create index if not exists stock_tips_news_idx on public.stock_tips (news_item_id);
create index if not exists stock_tips_result_news_idx on public.stock_tips (result_news_id);
comment on table public.stock_tips is 'Stock news with a lead (ADR-119): the hidden plan per hint. Internal; read through get_stock_news().';
revoke all on public.stock_tips from public, anon, authenticated;

create or replace function public.stock_news_run_due(p_now timestamptz default null)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_cfg      jsonb := public.config_jsonb('stockNews');
  v_now      timestamptz := coalesce(p_now, public.game_now());
  v_every    double precision;
  v_lead_min double precision;
  v_lead_max double precision;
  v_min      integer;
  v_max      integer;
  v_rel      integer;
  v_settled  integer := 0;
  v_new      integer := 0;
  t          public.stock_tips;
  s          record;
  v_dir      smallint;
  v_move     integer;
  v_strength smallint;
  v_head     text;
  v_body     text;
  v_news     bigint;
  v_up       text[] := array[
    'Analysten heben den Daumen für {name}', '{name}: Großauftrag in Sicht', 'Gerücht: {name} steht vor starken Zahlen',
    '{name} gewinnt neue Kunden', 'Insider rechnen bei {name} mit Rückenwind'];
  v_down     text[] := array[
    'Analysten warnen vor {name}', '{name}: Lieferprobleme befürchtet', 'Gerücht: {name} verfehlt die Erwartungen',
    '{name} verliert einen wichtigen Kunden', 'Gegenwind für {name} erwartet'];
  v_words    text[] := array['leicht', 'spürbar', 'deutlich'];
begin
  if v_cfg is null or jsonb_typeof(v_cfg) <> 'object' then
    return jsonb_build_object('skipped', 'no_config');
  end if;
  -- same lock as the minute job: never beside a running tick
  perform pg_advisory_xact_lock(7311001);
  v_every    := greatest(1, public.cfg_num(v_cfg, '{everyMinutes}', 12));
  v_lead_min := greatest(1, public.cfg_num(v_cfg, '{leadMinMinutes}', 10));
  v_lead_max := greatest(v_lead_min, public.cfg_num(v_cfg, '{leadMaxMinutes}', 40));
  v_min      := greatest(1, public.cfg_num(v_cfg, '{minMoveBps}', 300))::integer;
  v_max      := greatest(v_min, public.cfg_num(v_cfg, '{maxMoveBps}', 1200)::integer);
  v_rel      := least(10000, greatest(0, public.cfg_num(v_cfg, '{reliabilityBps}', 7500)))::integer;

  -- 1. hints whose time has come
  for t in select * from public.stock_tips x where x.applied_at is null and x.due_at <= v_now order by x.due_at for update loop
    select sec.name, sec.status into s from public.securities sec where sec.id = t.security_id;
    if t.comes_true and s.status = 'listed' then
      perform public.event_price_shock(t.security_id, t.direction * t.move_bps, v_now);
      v_head := case when t.direction > 0 then s.name || ' legt zu: Die Erwartungen haben sich bestätigt'
                     else s.name || ' gibt nach: Die Warnungen haben sich bestätigt' end;
    else
      v_head := 'Entwarnung bei ' || s.name || ': Die Meldung hat sich nicht bestätigt';
    end if;
    insert into public.news_items (category, headline, body, importance, security_id, published_at)
    values ('company', v_head, null, 1, t.security_id, v_now) returning id into v_news;
    update public.stock_tips set applied_at = v_now, result_news_id = v_news where id = t.id;
    v_settled := v_settled + 1;
  end loop;

  -- 2. a new hint when the last one is old enough
  if not exists (select 1 from public.stock_tips x where x.published_at > v_now - make_interval(secs => v_every * 60 - 5)) then
    select sec.id, sec.name into s
      from public.securities sec
     where sec.kind = 'stock' and sec.status = 'listed'
       and not exists (select 1 from public.stock_tips x where x.security_id = sec.id and x.applied_at is null)
     order by random() limit 1;
    if s.id is not null then
      v_dir := case when random() < 0.5 then 1 else -1 end;
      v_move := v_min + floor(random() * (v_max - v_min + 1))::integer;
      v_strength := least(3, 1 + floor(3.0 * (v_move - v_min) / greatest(1, v_max - v_min + 1)))::smallint;
      v_head := replace(case when v_dir > 0 then v_up[1 + floor(random() * array_length(v_up, 1))::integer]
                             else v_down[1 + floor(random() * array_length(v_down, 1))::integer] end, '{name}', s.name);
      v_body := case when v_dir > 0 then 'Beobachter rechnen in Kürze mit einem ' || v_words[v_strength] || ' steigenden Kurs.'
                     else 'Beobachter rechnen in Kürze mit einem ' || v_words[v_strength] || ' fallenden Kurs.' end
                || ' Sicher ist das nicht.';
      insert into public.news_items (category, headline, body, importance, security_id, published_at)
      values ('company', v_head, v_body, v_strength, s.id, v_now) returning id into v_news;
      insert into public.stock_tips (security_id, news_item_id, direction, move_bps, strength, comes_true, headline, body,
                                     published_at, due_at)
      values (s.id, v_news, v_dir, v_move, v_strength, random() * 10000 < v_rel, v_head, v_body, v_now,
              v_now + make_interval(secs => 60 * (v_lead_min + random() * (v_lead_max - v_lead_min))));
      v_new := 1;
    end if;
  end if;

  delete from public.stock_tips x
   where x.applied_at is not null
     and x.published_at < v_now - make_interval(hours => greatest(1, public.cfg_num(v_cfg, '{keepHours}', 24))::integer);
  return jsonb_build_object('settled', v_settled, 'published', v_new);
end;
$$;
comment on function public.stock_news_run_due(timestamptz) is
  'Internal, cron every minute (ADR-119): settles due stock hints and publishes a new one when it is time.';

create or replace function public.get_stock_news(p_limit integer default 20)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_player uuid;
begin
  v_player := public.require_player();
  return jsonb_build_object(
    'reliability_bps', least(10000, greatest(0, public.config_double('stockNews', '{reliabilityBps}', 7500)))::integer,
    'items', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', x.id, 'ticker', s.ticker, 'name', s.name, 'headline', x.headline, 'body', x.body,
               'direction', case when x.direction > 0 then 'up' else 'down' end, 'strength', x.strength,
               'published_at', x.published_at, 'due_at', x.due_at,
               'status', case when x.applied_at is null then 'open' when x.comes_true then 'confirmed' else 'fizzled' end,
               'move_bps', case when x.applied_at is not null and x.comes_true then x.direction * x.move_bps end)
             order by x.published_at desc, x.id desc)
        from (select t.* from public.stock_tips t order by t.published_at desc, t.id desc
               limit least(50, greatest(1, coalesce(p_limit, 20)))) x
        join public.securities s on s.id = x.security_id), '[]'::jsonb));
end;
$$;
comment on function public.get_stock_news(integer) is 'RPC: the latest stock hints with their state (ADR-119).';

revoke all on function public.stock_news_run_due(timestamptz) from public, anon, authenticated;
grant execute on function public.stock_news_run_due(timestamptz) to service_role;
revoke all on function public.get_stock_news(integer) from public, anon;
grant execute on function public.get_stock_news(integer) to authenticated, service_role;

-- Its own cron job, so the minute job stays short. Skipped where pg_cron is not installed (local tests).
do $$
begin
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    if exists (select 1 from cron.job where jobname = 'nexa-stock-news') then
      perform cron.unschedule('nexa-stock-news');
    end if;
    perform cron.schedule('nexa-stock-news', '* * * * *', 'select public.stock_news_run_due()');
  end if;
end;
$$;

-- ===== supabase/updates/20261203000700_friend_holdings.sql =====
-- ===== idempotent copy of migrations/20261203000700_friend_holdings.sql =====
-- (the migration itself is written idempotently; keep both files identical below this line)
-- =============================================================================
-- NEXA · 0700 · Friends see each other's investments (ADR-121)
-- =============================================================================
-- get_player_holdings(p_nickname) (authenticated): what a player holds and how much, for the player themselves and
-- for their friends. Everyone else only learns that it is private.
--   {"visible": true,  "total_cents", "positions": [{"ticker", "name", "kind", "sector", "quantity_e6",
--                                                    "value_cents", "share_bps"}]}   -- biggest first
--   {"visible": false, "total_cents": null, "positions": []}
-- Idempotent: runs unchanged as supabase/updates/20261203000700_friend_holdings.sql.

create or replace function public.get_player_holdings(p_nickname text)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_me     uuid;
  v_target uuid;
  v_total  bigint;
begin
  v_me := public.require_player();
  v_target := public.player_by_handle(p_nickname);
  if v_target is null then
    perform public.api_error('player_not_found');
  end if;
  if v_target <> v_me and not public.are_friends(v_me, v_target) then
    return jsonb_build_object('visible', false, 'total_cents', null, 'positions', '[]'::jsonb);
  end if;
  select coalesce(sum(public.value_cents(pos.quantity_e6, coalesce(q.bid_e4, q.last_price_e4))), 0)::bigint into v_total
    from public.positions pos join public.security_quotes q on q.security_id = pos.security_id
   where pos.player_id = v_target and pos.status = 'open' and pos.quantity_e6 > 0;
  return jsonb_build_object(
    'visible', true,
    'total_cents', v_total,
    'positions', coalesce((
      select jsonb_agg(jsonb_build_object(
               'ticker', x.ticker, 'name', x.name, 'kind', x.kind, 'sector', x.sector_key, 'quantity_e6', x.quantity_e6,
               'value_cents', x.val,
               'share_bps', case when v_total > 0 then round(x.val * 10000.0 / v_total)::integer else 0 end)
             order by x.val desc, x.ticker)
        from (select s.ticker, s.name, s.kind, s.sector_key, sum(pos.quantity_e6)::bigint as quantity_e6,
                     sum(public.value_cents(pos.quantity_e6, coalesce(q.bid_e4, q.last_price_e4)))::bigint as val
                from public.positions pos
                join public.securities s on s.id = pos.security_id
                join public.security_quotes q on q.security_id = pos.security_id
               where pos.player_id = v_target and pos.status = 'open' and pos.quantity_e6 > 0
               group by s.ticker, s.name, s.kind, s.sector_key) x), '[]'::jsonb));
end;
$$;
comment on function public.get_player_holdings(text) is
  'RPC: the investments of a player, visible to the player and to friends (ADR-121).';
revoke all on function public.get_player_holdings(text) from public, anon;
grant execute on function public.get_player_holdings(text) to authenticated, service_role;

-- ===== supabase/updates/20261203000800_tick_every_10s.sql =====
-- ===== idempotent copy of migrations/20261203000800_tick_every_10s.sql =====
-- (the migration itself is written idempotently; keep both files identical below this line)
-- =============================================================================
-- NEXA · 0800 · Market tick every 10 seconds (ADR-122)
-- =============================================================================
-- The tick wrote prices, candles and quotes for every stock and coin every 5 seconds; on a small database that used
-- up the disk budget. game_config.time.tickSeconds and crypto.tickSeconds are 10 now; the simulation scales its
-- moves with the interval, so the daily volatility stays the same. The cron job follows here.
-- Idempotent: runs unchanged as supabase/updates/20261203000800_tick_every_10s.sql.
do $$
begin
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    if exists (select 1 from cron.job where jobname = 'nexa-market-tick') then
      perform cron.unschedule('nexa-market-tick');
    end if;
    begin
      perform cron.schedule('nexa-market-tick', '10 seconds', 'select public.market_tick()');
    exception when others then
      raise warning 'pg_cron cannot schedule every 10 seconds (%): the market ticks once per minute instead', sqlerrm;
      perform cron.schedule('nexa-market-tick', '* * * * *', 'select public.market_tick()');
    end;
  end if;
end;
$$;

-- ===== supabase/updates/20261203000900_snapshot_cache.sql =====
-- ===== idempotent copy of migrations/20261203000900_snapshot_cache.sql =====
-- (the migration itself is written idempotently; keep both files identical below this line)
-- =============================================================================
-- NEXA · 0900 · The market snapshot is built once per tick, not once per request (ADR-123)
-- =============================================================================
-- Every open tab asks for get_market_snapshot() every tick. The answer is the same for every player, but each call
-- built it anew (all quotes, logos, money supply over the ledger): about 0.5 s of database time per call, thousands
-- of calls an hour. Now the first call of a tick builds it and stores it in market_snapshot_cache; every other call
-- of that tick reads the stored answer. Only server_time is added per call.
-- Idempotent: runs unchanged as supabase/updates/20261203000900_snapshot_cache.sql.

create table if not exists public.market_snapshot_cache (
  id        boolean primary key default true check (id),
  tick_seq  bigint not null,
  built_at  timestamptz not null,
  payload   jsonb not null
);
alter table public.market_snapshot_cache enable row level security;
revoke all on public.market_snapshot_cache from public, anon, authenticated;
comment on table public.market_snapshot_cache is 'The market snapshot of the latest tick (ADR-123). Internal; read through get_market_snapshot().';

-- Not stable any more: the first call of a tick writes the cache.
drop function if exists public.get_market_snapshot();
create function public.get_market_snapshot()
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_now     timestamptz := public.game_now();
  v_tick    bigint;
  v_cache   public.market_snapshot_cache;
  v_index   jsonb;
  v_secs    jsonb;
  v_payload jsonb;
begin
  perform public.require_player();
  select coalesce(r.tick_seq, 0) into v_tick from public.sim_runtime r where r.id;
  select * into v_cache from public.market_snapshot_cache c where c.id;
  -- the same tick, and not older than a minute (a paused market still refreshes its economy figures)
  if v_cache.id is not null and v_cache.tick_seq = coalesce(v_tick, 0) and v_cache.built_at > now() - interval '1 minute' then
    return v_cache.payload || jsonb_build_object('server_time', v_now);
  end if;

  select jsonb_build_object(
           'ticker', upper(i.key), 'name', s.name, 'value_e4', q.last_price_e4,
           'prev_close_e4', coalesce(q.prev_close_e4, q.last_price_e4), 'change_bps', q.change_bps,
           'day_high_e4', q.day_high_e4, 'day_low_e4', q.day_low_e4)
    into v_index
    from public.indices i
    join public.securities s on s.id = i.security_id
    join public.security_quotes q on q.security_id = s.id
   order by i.created_at
   limit 1;

  select coalesce(jsonb_agg(jsonb_build_object(
           'id', s.id, 'ticker', s.ticker, 'name', s.name, 'kind', s.kind,
           'sector_key', s.sector_key, 'size_class', c.tier,
           'last_price_e4', q.last_price_e4, 'bid_e4', q.bid_e4, 'ask_e4', q.ask_e4,
           'prev_close_e4', coalesce(q.prev_close_e4, q.last_price_e4), 'change_bps', q.change_bps,
           'day_high_e4', coalesce(q.day_high_e4, q.last_price_e4), 'day_low_e4', coalesce(q.day_low_e4, q.last_price_e4),
           'day_volume_e6', q.day_volume_e6, 'market_cap_cents', case when s.kind = 'stock' then q.market_cap_cents end,
           'term_game_years', b.term_game_years, 'coupon_bps', b.coupon_bps,
           'yield_bps', case when s.kind = 'bond' then q.yield_bps end,
           'matures_at', b.matures_at, 'face_value_cents', b.face_value_cents,
           'company_id', s.company_id, 'brand_color', c.brand_color,
           'logo', case when s.company_id is not null then public.company_logo(s.company_id) end,
           'company_kind', case when c.id is not null and not c.is_ai then 'player' else 'ai' end)
         order by case s.kind when 'stock' then 0 else 1 end, sec.sort_order, b.term_game_years, s.ticker), '[]'::jsonb)
    into v_secs
    from public.securities s
    join public.security_quotes q on q.security_id = s.id
    left join public.companies c on c.id = s.company_id
    left join public.sectors sec on sec.key = s.sector_key
    left join public.bonds b on b.security_id = s.id
   where s.status = 'listed' and s.kind in ('stock', 'bond');

  v_payload := jsonb_build_object(
    'tick_seq',        (select r.tick_seq from public.sim_runtime r where r.id),
    'last_tick_at',    (select r.last_tick_at from public.sim_runtime r where r.id),
    'session',         public.market_session_at(v_now),
    'paused',          coalesce((select r.is_paused from public.sim_runtime r where r.id), false),
    'policy_rate_bps', (select cb.policy_rate_bps from public.central_bank_state cb where cb.id),
    'day_start',       public.trading_day_start(v_now),
    'index',           v_index,
    'securities',      v_secs,
    'economy',         jsonb_build_object(
                         'money_supply_cents',      public.money_supply_cents(),
                         'treasury_cents',          public.treasury_balance_cents(),
                         'basic_income_factor_bps', public.basic_income_factor_bps(),
                         'total_supply_cents',      public.config_bigint('money', '{totalSupplyCents}', 1000000000000)));

  insert into public.market_snapshot_cache (id, tick_seq, built_at, payload)
  values (true, coalesce(v_tick, 0), now(), v_payload)
  on conflict (id) do update set tick_seq = excluded.tick_seq, built_at = excluded.built_at, payload = excluded.payload;
  return v_payload || jsonb_build_object('server_time', v_now);
end;
$$;
comment on function public.get_market_snapshot() is 'RPC: quotes, index and economy of the latest tick, built once per tick (ADR-123).';
revoke all on function public.get_market_snapshot() from public, anon;
grant execute on function public.get_market_snapshot() to authenticated, service_role;

-- Listings, names, colours and logos change within a tick (IPO, new logo): then the cached answer is dropped.
create or replace function public.market_snapshot_invalidate()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  delete from public.market_snapshot_cache;
  return null;
end;
$$;
revoke all on function public.market_snapshot_invalidate() from public, anon, authenticated;

drop trigger if exists market_snapshot_securities_ins on public.securities;
create trigger market_snapshot_securities_ins after insert or delete on public.securities
  for each statement execute function public.market_snapshot_invalidate();
drop trigger if exists market_snapshot_securities_upd on public.securities;
create trigger market_snapshot_securities_upd after update on public.securities
  for each row when (old.status is distinct from new.status or old.name is distinct from new.name
                     or old.sector_key is distinct from new.sector_key or old.company_id is distinct from new.company_id)
  execute function public.market_snapshot_invalidate();
drop trigger if exists market_snapshot_companies_upd on public.companies;
create trigger market_snapshot_companies_upd after update on public.companies
  for each row when (old.brand_color is distinct from new.brand_color or old.is_ai is distinct from new.is_ai
                     or old.tier is distinct from new.tier)
  execute function public.market_snapshot_invalidate();
drop trigger if exists market_snapshot_logos_upd on public.player_companies;
create trigger market_snapshot_logos_upd after update on public.player_companies
  for each row when (old.logo is distinct from new.logo or old.logo_hidden is distinct from new.logo_hidden)
  execute function public.market_snapshot_invalidate();

-- ===== supabase/updates/20261203001000_split_minute_job.sql =====
-- ===== idempotent copy of migrations/20261203001000_split_minute_job.sql =====
-- (the migration itself is written idempotently; keep both files identical below this line)
-- =============================================================================
-- NEXA · 1000 · The minute job in five short parts (ADR-123)
-- =============================================================================
-- run_due_jobs() did everything in one transaction: on the live database about 13 seconds every minute, holding the
-- tick lock and the rows it touched; players waited behind it. The cron job now runs run_due_part() for five parts,
-- each its own short transaction:
--   core       calendar, bootstrap, crypto, quarter closes, bonds, daily maintenance
--   companies  operating hours of player companies, company events, deals (in this order, as before)
--   jobs       quit notices, share offers, AI job postings, wages
--   art        artwork auctions
--   social     rich list snapshot, feed and league, announced events
-- run_due_jobs() stays and runs all parts in one go (tests, manual catch-up).
-- Also (ADR-117): missions about limit orders that are still running are ended.
-- Idempotent: runs unchanged as supabase/updates/20261203001000_split_minute_job.sql.

create or replace function public.run_due_part(p_part text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_now      timestamptz;
  v_result   jsonb := '{}'::jsonb;
  v_closed   jsonb := '[]'::jsonb;
  v_latest   bigint;
  q          record;
  v_run      bigint;
begin
  -- waits for a running tick (ticks only try the lock and skip)
  perform pg_advisory_xact_lock(7311001);
  v_now := public.game_now();
  if p_part = 'core' then
  perform public.ensure_game_quarters(3);

  if not exists (select 1 from public.candles limit 1) or not public.money_genesis_done()
     or not exists (select 1 from public.rich_tycoons) then
    v_result := v_result || jsonb_build_object('bootstrap', public.market_bootstrap());
  end if;

  -- cryptocurrencies (ADR-101) first: coin rows are locked before any ledger account (same order as trades)
  v_result := v_result || jsonb_build_object('crypto', public.crypto_run_due(v_now));

  -- first run on a database: older quarters are skipped, only the latest ended one is closed
  if not exists (select 1 from public.job_runs j where j.job_name = 'quarter_close') then
    select gq.id into v_latest from public.game_quarters gq
     where gq.ends_at <= v_now and gq.status <> 'closed' order by gq.ends_at desc limit 1;
    for q in select gq.id from public.game_quarters gq
              where gq.ends_at <= v_now and gq.status <> 'closed' and gq.id <> coalesce(v_latest, -1)
    loop
      update public.game_quarters set status = 'closed', closed_at = now() where id = q.id;
      insert into public.job_runs (job_name, run_key, status, finished_at, details)
      values ('quarter_close', q.id::text, 'succeeded', now(), '{"skipped": "before_first_run"}'::jsonb)
      on conflict do nothing;
    end loop;
  end if;

  for q in select gq.id from public.game_quarters gq
            where gq.ends_at <= v_now and gq.status <> 'closed'
            order by gq.ends_at limit 8
  loop
    v_closed := v_closed || public.close_game_quarter(q.id);
  end loop;
  v_result := v_result || jsonb_build_object('quarters', v_closed);
  -- bonds that matured between quarter closes (or after a downtime)
  if exists (select 1 from public.bonds bd join public.securities s on s.id = bd.security_id
              where s.status = 'listed' and bd.matures_at <= v_now) then
    v_result := v_result || jsonb_build_object('bonds_redeemed', public.redeem_matured_bonds(v_now));
  end if;
  v_result := v_result || jsonb_build_object('bonds_issued', public.ensure_bond_series());

  -- daily maintenance (first run per UTC day)
  insert into public.job_runs (job_name, run_key) values ('maintenance', to_char(now() at time zone 'UTC', 'YYYY-MM-DD'))
  on conflict (job_name, run_key) do nothing
  returning id into v_run;
  if v_run is not null then
    v_result := v_result || jsonb_build_object('maintenance', public.run_maintenance());
    -- price_ticks: keep about one day (candles hold the history), cron log: one day
    perform public.maintain_price_tick_partitions(3, 1);
    if to_regclass('cron.job_run_details') is not null then
      begin
        execute 'delete from cron.job_run_details where end_time < now() - interval ''1 day''';
      exception when others then
        raise warning 'NEXA: could not prune cron.job_run_details: %', sqlerrm;
      end;
    end if;
    delete from public.job_runs j where j.job_name = 'maintenance' and j.started_at < now() - interval '30 days';
    update public.job_runs set status = 'succeeded', finished_at = now() where id = v_run;
  end if;
  elsif p_part = 'companies' then
  v_result := v_result || jsonb_build_object('player_companies', public.player_companies_run_due());
  v_result := v_result || jsonb_build_object('company_events', public.company_events_run_due());
  -- deals between players (ADR-098): after the company hours, so supply contracts see both companies' hours
  v_result := v_result || jsonb_build_object('deals', public.deals_run_due());

  elsif p_part = 'jobs' then
  -- jobs: AI postings of the running quarter, wages of AI-company jobs in whole hours
  v_result := v_result || jsonb_build_object('quit_notices', public.process_quit_notices(null));
  v_result := v_result || jsonb_build_object('share_offers', public.close_due_offers(null));
  v_result := v_result || jsonb_build_object('job_postings', public.refresh_ai_job_postings(),
                                             'salaries_paid', public.accrue_salaries(null));

  elsif p_part = 'art' then
  -- artworks (ADR-080): due auctions are settled, the gallery starts the auctions of the day
  v_result := v_result || jsonb_build_object('artworks', public.artworks_run_due());

  elsif p_part = 'social' then
  -- rich list snapshot every richList.snapshotMinutes (rank news, 24 h changes, state missions)
  v_result := v_result || jsonb_build_object('rich_list', public.rich_list_snapshot(false));

  -- weekly league and feed upkeep (M4f, ADR-088/089) and announced events (M4g, ADR-090): kept in this redefinition
  v_result := v_result || jsonb_build_object('social', public.social_run_due());
  v_result := v_result || jsonb_build_object('events', public.events_run_due());

  else
    perform public.api_error('invalid_argument');
  end if;
  return v_result;
end;
$$;
comment on function public.run_due_part(text) is
  'Internal, cron every minute (ADR-123): one part of the due jobs (core, companies, jobs, art, social), own transaction.';
revoke all on function public.run_due_part(text) from public, anon, authenticated;
grant execute on function public.run_due_part(text) to service_role;

do $$
declare
  p text;
begin
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    if exists (select 1 from cron.job where jobname = 'nexa-due-jobs') then
      perform cron.unschedule('nexa-due-jobs');
    end if;
    foreach p in array array['core', 'companies', 'jobs', 'art', 'social'] loop
      if exists (select 1 from cron.job where jobname = 'nexa-due-' || p) then
        perform cron.unschedule('nexa-due-' || p);
      end if;
      perform cron.schedule('nexa-due-' || p, '* * * * *', format('select public.run_due_part(%L)', p));
    end loop;
  end if;
end;
$$;

-- Limit orders are gone (ADR-117): running missions about them end as well.
update public.player_missions m set status = 'expired'
  from public.mission_templates t
 where t.key = m.template_key and m.status = 'active'
   and t.metric in ('limit_orders_placed', 'limit_orders_filled');

-- ===== supabase/updates/20261203001100_net_worth_history.sql =====
-- ===== idempotent copy of migrations/20261203001100_net_worth_history.sql =====
-- (the migration itself is written idempotently; keep both files identical below this line)
-- =============================================================================
-- NEXA · 1100 · The own net worth over time, for the portfolio chart (ADR-124)
-- =============================================================================
-- get_my_net_worth_history(p_hours) (authenticated): the player's net worth from the rich list snapshots (every few
-- minutes, kept 8 days), at most about 300 points: every snapshot for a day, hourly buckets for longer ranges.
--   {"points": [{"at", "net_worth_cents"}]}   -- oldest first
-- Idempotent: runs unchanged as supabase/updates/20261203001100_net_worth_history.sql.

create or replace function public.get_my_net_worth_history(p_hours integer default 24)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_player uuid := public.require_player();
  v_hours  integer := least(192, greatest(1, coalesce(p_hours, 24)));
  v_from   timestamptz := public.game_now() - make_interval(hours => v_hours);
  v_bucket interval := case when v_hours <= 24 then interval '5 minutes' else interval '1 hour' end;
begin
  return jsonb_build_object('points', coalesce((
    select jsonb_agg(jsonb_build_object('at', b.at, 'net_worth_cents', b.nw) order by b.at)
      from (select date_bin(v_bucket, s.taken_at, '2000-01-01 00:00:00+00') as at,
                   (array_agg(s.net_worth_cents order by s.taken_at desc))[1] as nw
              from public.rich_list_snapshots s
             where s.entity_id = v_player and s.entity_kind = 'player' and s.taken_at >= v_from
             group by 1) b), '[]'::jsonb));
end;
$$;
comment on function public.get_my_net_worth_history(integer) is
  'RPC: the own net worth over the last hours, from the rich list snapshots (ADR-124).';
revoke all on function public.get_my_net_worth_history(integer) from public, anon;
grant execute on function public.get_my_net_worth_history(integer) to authenticated, service_role;

-- ===== supabase/updates/20261203001200_more_stock_news.sql =====
-- ===== idempotent copy of migrations/20261203001200_more_stock_news.sql =====
-- (the migration itself is written idempotently; keep both files identical below this line)
-- =============================================================================
-- NEXA · 1200 · Many more kinds of stock news, good and bad (ADR-119 follow-up)
-- =============================================================================
-- 15 good and 15 bad events (big orders, raised outlook, star investor, buyback ... affair, capital increase,
-- racism allegations, recall, data leak, raid ...), each with its own headline and text. Up and down stay equally
-- likely. Same rhythm and mechanics as before.
-- Idempotent: runs unchanged as supabase/updates/20261203001200_more_stock_news.sql.

create or replace function public.stock_news_run_due(p_now timestamptz default null)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_cfg      jsonb := public.config_jsonb('stockNews');
  v_now      timestamptz := coalesce(p_now, public.game_now());
  v_every    double precision;
  v_lead_min double precision;
  v_lead_max double precision;
  v_min      integer;
  v_max      integer;
  v_rel      integer;
  v_settled  integer := 0;
  v_new      integer := 0;
  t          public.stock_tips;
  s          record;
  v_dir      smallint;
  v_move     integer;
  v_strength smallint;
  v_head     text;
  v_body     text;
  v_news     bigint;
  v_good     jsonb := jsonb_build_array(
      jsonb_build_array('Rekordauftrag für {name}', '{name} gewinnt einen Großkunden. Der Auftrag dürfte den Umsatz {w} anheben.'),
      jsonb_build_array('{name} hebt die Prognose an', 'Die Geschäfte laufen besser als geplant. Analysten erwarten einen {w} steigenden Kurs.'),
      jsonb_build_array('Neuer Chef-Entwickler wechselt zu {name}', 'Ein bekannter Kopf aus der Branche kommt an Bord. Anleger dürften das {w} honorieren.'),
      jsonb_build_array('{name} gewinnt Branchenpreis', 'Das Unternehmen wird für sein neues Produkt ausgezeichnet. Rückenwind für die Aktie erwartet.'),
      jsonb_build_array('Übernahmegerüchte um {name}', 'Ein großer Konkurrent soll Interesse haben. Spekulanten könnten den Kurs {w} treiben.'),
      jsonb_build_array('{name} startet Aktienrückkauf', 'Das Unternehmen kauft eigene Aktien zurück. Das stützt den Kurs {w}.'),
      jsonb_build_array('Staatlicher Großauftrag für {name}', 'Ein mehrjähriger Vertrag mit der öffentlichen Hand ist unterschrieben.'),
      jsonb_build_array('{name}: Neues Produkt ausverkauft', 'Die Nachfrage übertrifft alle Erwartungen. Händler rechnen mit einem {w} steigenden Kurs.'),
      jsonb_build_array('Patent für {name} erteilt', 'Eine wichtige Technologie ist jetzt geschützt. Der Vorsprung dürfte sich auszahlen.'),
      jsonb_build_array('{name} senkt die Kosten deutlich', 'Ein Sparprogramm wirkt schneller als gedacht. Die Marge steigt.'),
      jsonb_build_array('Star-Investor steigt bei {name} ein', 'Ein bekannter Anleger hat ein großes Paket gekauft. Andere könnten folgen.'),
      jsonb_build_array('{name} erschließt neuen Markt', 'Der Start im Ausland läuft besser als geplant.'),
      jsonb_build_array('Kooperation: {name} und ein Branchenriese', 'Die Partnerschaft soll beiden Seiten neue Kunden bringen.'),
      jsonb_build_array('Analysten-Upgrade: {name} jetzt Kaufempfehlung', 'Mehrere Häuser heben ihr Kursziel {w} an.'),
      jsonb_build_array('Sonderdividende bei {name} erwartet', 'Die Kasse ist voll. Aktionäre dürfen auf eine Extra-Ausschüttung hoffen.'));
  v_bad      jsonb := jsonb_build_array(
      jsonb_build_array('Affäre erschüttert {name}', 'Die Chefetage von {name} steht wegen einer Affäre in der Kritik. Anleger werden nervös.'),
      jsonb_build_array('{name} plant Kapitalerhöhung', 'Neue Aktien sollen ausgegeben werden. Das verwässert die Anteile, der Kurs dürfte {w} nachgeben.'),
      jsonb_build_array('Rassismus-Vorwürfe gegen {name}', 'Ehemalige Mitarbeiter erheben schwere Vorwürfe. Kunden kündigen erste Verträge.'),
      jsonb_build_array('Rückruf bei {name}', 'Ein fehlerhaftes Produkt muss zurück in die Werkstatt. Das wird teuer.'),
      jsonb_build_array('Datenleck bei {name}', 'Kundendaten sind im Netz aufgetaucht. Die Aufsicht prüft.'),
      jsonb_build_array('{name}-Chef tritt überraschend zurück', 'Die Gründe sind unklar. Der Markt mag keine Unsicherheit.'),
      jsonb_build_array('Razzia bei {name}', 'Ermittler durchsuchen die Zentrale wegen des Verdachts auf Bilanztricks.'),
      jsonb_build_array('{name} senkt die Prognose', 'Das Geschäft läuft schwächer als erwartet. Analysten rechnen mit einem {w} fallenden Kurs.'),
      jsonb_build_array('Streik legt {name} lahm', 'Die Belegschaft legt die Arbeit nieder. Lieferungen verzögern sich.'),
      jsonb_build_array('Großkunde springt bei {name} ab', 'Ein wichtiger Vertrag wird nicht verlängert.'),
      jsonb_build_array('Analysten-Downgrade für {name}', 'Mehrere Häuser streichen ihre Kaufempfehlung und senken das Kursziel.'),
      jsonb_build_array('{name} verliert Patentstreit', 'Ein Gericht gibt dem Konkurrenten recht. Lizenzzahlungen drohen.'),
      jsonb_build_array('Umweltskandal bei {name}', 'Ein Werk soll Grenzwerte überschritten haben. Bußgelder sind wahrscheinlich.'),
      jsonb_build_array('Lieferkette reißt bei {name}', 'Ein wichtiger Zulieferer fällt aus. Die Produktion stockt.'),
      jsonb_build_array('Leerverkäufer wetten gegen {name}', 'Ein bekannter Fonds hält die Aktie für überbewertet.'));
  v_pick     jsonb;
  v_words    text[] := array['leicht', 'spürbar', 'deutlich'];
begin
  if v_cfg is null or jsonb_typeof(v_cfg) <> 'object' then
    return jsonb_build_object('skipped', 'no_config');
  end if;
  -- same lock as the minute job: never beside a running tick
  perform pg_advisory_xact_lock(7311001);
  v_every    := greatest(1, public.cfg_num(v_cfg, '{everyMinutes}', 12));
  v_lead_min := greatest(1, public.cfg_num(v_cfg, '{leadMinMinutes}', 10));
  v_lead_max := greatest(v_lead_min, public.cfg_num(v_cfg, '{leadMaxMinutes}', 40));
  v_min      := greatest(1, public.cfg_num(v_cfg, '{minMoveBps}', 300))::integer;
  v_max      := greatest(v_min, public.cfg_num(v_cfg, '{maxMoveBps}', 1200)::integer);
  v_rel      := least(10000, greatest(0, public.cfg_num(v_cfg, '{reliabilityBps}', 7500)))::integer;

  -- 1. hints whose time has come
  for t in select * from public.stock_tips x where x.applied_at is null and x.due_at <= v_now order by x.due_at for update loop
    select sec.name, sec.status into s from public.securities sec where sec.id = t.security_id;
    if t.comes_true and s.status = 'listed' then
      perform public.event_price_shock(t.security_id, t.direction * t.move_bps, v_now);
      v_head := case when t.direction > 0 then s.name || ' legt zu: Die Erwartungen haben sich bestätigt'
                     else s.name || ' gibt nach: Die Warnungen haben sich bestätigt' end;
    else
      v_head := 'Entwarnung bei ' || s.name || ': Die Meldung hat sich nicht bestätigt';
    end if;
    insert into public.news_items (category, headline, body, importance, security_id, published_at)
    values ('company', v_head, null, 1, t.security_id, v_now) returning id into v_news;
    update public.stock_tips set applied_at = v_now, result_news_id = v_news where id = t.id;
    v_settled := v_settled + 1;
  end loop;

  -- 2. a new hint when the last one is old enough
  if not exists (select 1 from public.stock_tips x where x.published_at > v_now - make_interval(secs => v_every * 60 - 5)) then
    select sec.id, sec.name into s
      from public.securities sec
     where sec.kind = 'stock' and sec.status = 'listed'
       and not exists (select 1 from public.stock_tips x where x.security_id = sec.id and x.applied_at is null)
     order by random() limit 1;
    if s.id is not null then
      v_dir := case when random() < 0.5 then 1 else -1 end;
      v_move := v_min + floor(random() * (v_max - v_min + 1))::integer;
      v_strength := least(3, 1 + floor(3.0 * (v_move - v_min) / greatest(1, v_max - v_min + 1)))::smallint;
      v_pick := case when v_dir > 0 then v_good -> floor(random() * jsonb_array_length(v_good))::integer
                     else v_bad -> floor(random() * jsonb_array_length(v_bad))::integer end;
      v_head := replace(v_pick ->> 0, '{name}', s.name);
      v_body := replace(replace(v_pick ->> 1, '{name}', s.name), '{w}', v_words[v_strength]) || ' Sicher ist das nicht.';
      insert into public.news_items (category, headline, body, importance, security_id, published_at)
      values ('company', v_head, v_body, v_strength, s.id, v_now) returning id into v_news;
      insert into public.stock_tips (security_id, news_item_id, direction, move_bps, strength, comes_true, headline, body,
                                     published_at, due_at)
      values (s.id, v_news, v_dir, v_move, v_strength, random() * 10000 < v_rel, v_head, v_body, v_now,
              v_now + make_interval(secs => 60 * (v_lead_min + random() * (v_lead_max - v_lead_min))));
      v_new := 1;
    end if;
  end if;

  delete from public.stock_tips x
   where x.applied_at is not null
     and x.published_at < v_now - make_interval(hours => greatest(1, public.cfg_num(v_cfg, '{keepHours}', 24))::integer);
  return jsonb_build_object('settled', v_settled, 'published', v_new);
end;
$$;

-- ===== supabase/updates/20261203001300_company_profile.sql =====
-- ===== idempotent copy of migrations/20261203001300_company_profile.sql =====
-- (the migration itself is written idempotently; keep both files identical below this line)
-- =============================================================================
-- NEXA · 1300 · Every company can be opened: staff and key facts (ADR-125)
-- =============================================================================
-- get_company_profile(p_company_id) (authenticated): the public profile of any company, AI or player, for every
-- player. Facts that a company shows anyway (team, product, stage, revenue and profit of the last quarter, value),
-- never its cash, debts or plans.
--   {"company": {"id", "name", "ticker", "sector", "is_ai", "tier", "brand_color", "logo", "idea", "founded_at",
--                "listed", "price_e4", "change_bps"},
--    "founder": {"nickname", "tag", "avatar_key"} | null,
--    "facts": {"value_cents", "revenue_cents", "profit_cents", "period": "quarter"|"ttm"|null, "staff",
--              "max_staff", "ai_workers", "product", "stage", "quality_bps", "awareness_bps"},
--    "members": [{"nickname", "tag", "avatar_key", "tier", "title", "since"}]}
-- get_company_org() is now open to every player as well (it shows the same people).
-- Idempotent: runs unchanged as supabase/updates/20261203001300_company_profile.sql.

create or replace function public.get_company_profile(p_company_id uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_player uuid := public.require_player();
  c        public.companies;
  pc       public.player_companies;
  r        public.player_company_reports;
  q        public.security_quotes;
  v_listed boolean := false;
begin
  select * into c from public.companies where id = p_company_id and dissolved_at is null;
  if c.id is null then
    perform public.api_error('company_not_found');
  end if;
  select * into pc from public.player_companies where company_id = c.id;
  if pc.company_id is not null then
    select x.* into r from public.player_company_reports x join public.game_quarters gq on gq.id = x.game_quarter_id
     where x.company_id = c.id order by gq.ends_at desc limit 1;
  end if;
  if c.security_id is not null then
    select * into q from public.security_quotes where security_id = c.security_id;
    v_listed := exists (select 1 from public.securities s where s.id = c.security_id and s.status = 'listed');
  end if;

  return jsonb_build_object(
    'company', jsonb_build_object(
      'id', c.id, 'name', c.name, 'ticker', c.ticker, 'sector', c.sector_key, 'is_ai', c.is_ai,
      'tier', coalesce(pc.tier, c.tier::text), 'brand_color', c.brand_color, 'logo', public.company_logo(c.id),
      'idea', coalesce(pc.idea, c.description), 'founded_at', c.founded_at, 'listed', v_listed,
      'price_e4', case when v_listed then q.last_price_e4 end, 'change_bps', case when v_listed then q.change_bps end),
    'founder', (select jsonb_build_object('nickname', p.nickname, 'tag', p.tag, 'avatar_key', p.avatar_key)
                  from public.profiles p where p.id = coalesce(pc.founder_id, c.founder_id)),
    'facts', jsonb_build_object(
      'value_cents', case when pc.company_id is not null and not v_listed then public.company_value_cents(c.id)
                          else q.market_cap_cents end,
      'revenue_cents', case when r.company_id is not null then r.revenue_cents
                            when c.is_ai then c.ttm_revenue_cents end,
      'profit_cents', case when r.company_id is not null then r.operating_profit_cents
                           when c.is_ai then c.ttm_net_income_cents end,
      'period', case when r.company_id is not null then 'quarter' when c.is_ai then 'ttm' end,
      'staff', case when pc.company_id is not null
                    then 1 + pc.ai_workers + (select count(*) from public.player_jobs j
                                               where j.company_id = c.id and j.status = 'active')::integer
                    else c.employee_count end,
      'max_staff', c.max_employees,
      'ai_workers', coalesce(pc.ai_workers, 0),
      'product', pc.product_key,
      'stage', case when pc.company_id is not null then public.company_stage(c.id) end,
      'quality_bps', case when r.company_id is not null then r.quality_bps end,
      'awareness_bps', case when r.company_id is not null then r.awareness_bps end),
    'members', coalesce((
      select jsonb_agg(jsonb_build_object('nickname', p.nickname, 'tag', p.tag, 'avatar_key', p.avatar_key, 'tier', j.tier,
                                          'title', coalesce(j.title, j.title_key), 'since', j.started_at)
                       order by case j.tier::text when 'c_level' then 5 when 'team_lead' then 4 when 'senior' then 3
                                                  when 'junior' then 2 else 1 end desc, j.started_at, p.nickname)
        from public.player_jobs j join public.profiles p on p.id = j.player_id
       where j.company_id = c.id and j.status = 'active'), '[]'::jsonb));
end;
$$;
comment on function public.get_company_profile(uuid) is
  'RPC: the public profile of any company (team, product, last quarter, value), for every player (ADR-125).';
revoke all on function public.get_company_profile(uuid) from public, anon;
grant execute on function public.get_company_profile(uuid) to authenticated, service_role;

create or replace function public.get_company_org(p_company_id uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_player uuid := public.require_player();
  pc       public.player_companies;
  c        public.companies;
begin
  select * into pc from public.player_companies where company_id = p_company_id and status = 'active';
  if pc.company_id is null then
    perform public.api_error('company_not_found');
  end if;
  select * into c from public.companies where id = p_company_id;
  -- open to every player (ADR-125): the org chart shows who works where, nothing more
  return jsonb_build_object(
    'company', jsonb_build_object('id', c.id, 'name', c.name, 'tier', pc.tier),
    'founder', (select jsonb_build_object('nickname', p.nickname, 'tag', p.tag, 'avatar_key', p.avatar_key,
                                          'is_me', p.id = v_player)
                  from public.profiles p where p.id = pc.founder_id),
    'members', coalesce((
      select jsonb_agg(jsonb_build_object('nickname', p.nickname, 'tag', p.tag, 'avatar_key', p.avatar_key, 'tier', j.tier,
                                          'title', coalesce(j.title, j.title_key), 'since', j.started_at,
                                          'is_me', j.player_id = v_player)
                       order by case j.tier::text when 'c_level' then 5 when 'team_lead' then 4 when 'senior' then 3
                                                  when 'junior' then 2 else 1 end desc, j.started_at, p.nickname)
        from public.player_jobs j join public.profiles p on p.id = j.player_id
       where j.company_id = p_company_id and j.status = 'active'), '[]'::jsonb),
    'ai_workers', pc.ai_workers,
    'ai_worker_skills', to_jsonb(coalesce(pc.ai_worker_skills, '{}'::text[])));
end;
$$;

-- ===== supabase/updates/20261203001400_fair_fill_price.sql =====
-- ===== idempotent copy of migrations/20261203001400_fair_fill_price.sql =====
-- (the migration itself is written idempotently; keep both files identical below this line)
-- =============================================================================
-- NEXA · 1400 · A fill pays for the price move it causes (ADR-126)
-- =============================================================================
-- Since players move prices strongly (ADR-120), the next tick lifts a stock by 0.01 x order value /
-- depthCentsPer100Bps (10.000 EUR: 10 % for a penny stock). The fill itself only paid the old, much smaller depth
-- slippage, so "buy, wait one tick, sell" earned the own move. Now a stock order's slippage uses the same player
-- depth: the fill pays about half of the move it causes, and selling right after pays half of its own move down.
-- A round trip loses spread, fees and a little slippage; holding a stock others buy still pays.
-- Idempotent: runs unchanged as supabase/updates/20261203001400_fair_fill_price.sql.

create or replace function public.place_order(
  p_request_id     uuid,
  p_ticker         text,
  p_side           text,
  p_type           text,
  p_quantity_e6    bigint default null,
  p_limit_price_e4 bigint default null,
  p_amount_cents   bigint default null
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player     uuid;
  v_replay     jsonb;
  v_trading    jsonb := coalesce(public.config_jsonb('trading'), '{}'::jsonb);
  v_abuse      jsonb := coalesce(public.config_jsonb('abuse'), '{}'::jsonb);
  v_scale      numeric := greatest(1, public.cfg_num(v_trading, '{quantityScale}', 1000000))::numeric;
  v_side       public.order_side;
  v_type       public.order_type;
  v_limit      bigint;
  s            public.securities;
  v_level      integer;
  v_cash       bigint;
  v_bid        bigint;
  v_ask        bigint;
  v_pending    bigint;
  v_regular    boolean;
  v_depth      double precision;
  v_a          double precision;
  v_pos        double precision;
  v_touch      bigint;
  v_qty        bigint;
  v_fill_qty   bigint := 0;
  v_fill_price bigint;
  v_rest       bigint;
  v_fee        bigint;
  v_min_value  bigint;
  v_need       bigint;
  v_reserve    bigint := 0;
  v_avail      bigint;
  v_net_amount bigint;
  v_order_id   uuid := gen_random_uuid();
  v_fill       jsonb;
  o            public.orders;
  v_prof       public.profiles;
  v_min_price  bigint;
begin
  v_player := public.require_player();
  if p_request_id is null then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'place_order');
  if v_replay is not null then
    return v_replay;
  end if;

  -- inputs -------------------------------------------------------------------
  if lower(coalesce(p_side, '')) not in ('buy', 'sell') or lower(coalesce(p_type, '')) not in ('market', 'limit')
     or (p_quantity_e6 is null) = (p_amount_cents is null) then
    perform public.api_error('invalid_argument');
  end if;
  v_side := lower(p_side)::public.order_side;
  v_type := lower(p_type)::public.order_type;
  if (p_quantity_e6 is not null and p_quantity_e6 < 1) or (p_amount_cents is not null and p_amount_cents < 1) then
    perform public.api_error('invalid_quantity');
  end if;
  if v_type = 'limit' then
    if p_limit_price_e4 is null or p_limit_price_e4 < 1 or p_limit_price_e4 > 100000000000 then
      perform public.api_error('invalid_price');
    end if;
    v_limit := p_limit_price_e4;
  end if;

  select * into s from public.securities where id = public.resolve_security(p_ticker);
  if s.id is null then
    perform public.api_error('unknown_security');
  end if;
  if s.kind not in ('stock', 'bond') or s.status <> 'listed' or not s.is_tradable then
    perform public.api_error('not_tradable');
  end if;
  if (select r.is_paused from public.sim_runtime r where r.id) then
    perform public.api_error('market_paused');
  end if;

  select p.level into v_level from public.profiles p where p.id = v_player;
  if v_type = 'limit' and v_level < public.unlock_level('limit_orders') then
    perform public.api_error('locked');
  end if;
  if s.kind = 'bond' and v_level < public.unlock_level('bonds') then
    perform public.api_error('locked');
  end if;

  if not public.rate_limit_hit(v_player, 'place_order',
           greatest(1, public.cfg_num(v_abuse, '{rateLimits,ordersPerMinute}', 20))::integer, 60)
     or not public.rate_limit_hit(v_player, 'place_order_day',
           greatest(1, public.cfg_num(v_abuse, '{rateLimits,ordersPerDay}', 500))::integer, 86400) then
    perform public.api_error('rate_limited');
  end if;

  -- locks, quote ---------------------------------------------------------------
  v_cash := public.lock_player_accounts(v_player);
  select q.bid_e4, q.ask_e4 into v_bid, v_ask from public.security_quotes q where q.security_id = s.id;
  select st.pending_player_flow_e6 into v_pending from public.security_sim_state st where st.security_id = s.id;
  if v_bid is null or v_ask is null then
    perform public.api_error('not_tradable');
  end if;
  v_pending   := coalesce(v_pending, 0);
  v_regular   := public.market_session_at(public.game_now()) = 'regular';
  v_depth     := public.security_depth(s.id, v_regular);                 -- whole shares
  v_a         := public.cfg_num(v_trading, '{priceImpact,impactBpsPerDepth}', 100) / 10000.0 / v_depth;
  v_fee       := greatest(0, public.cfg_num(v_trading, '{orderFeeCents}', 100))::bigint;
  v_min_value := greatest(1, public.cfg_num(v_trading, '{minOrderValueCents}', 100))::bigint;
  v_min_price := greatest(1, public.cfg_num(v_trading, '{minPriceE4}', 1))::bigint;
  if v_side = 'buy' then
    v_touch := v_ask;
    v_pos := greatest(v_pending, 0) / 1000000.0;
  else
    v_touch := v_bid;
    v_pos := greatest(-v_pending, 0) / 1000000.0;
  end if;
  -- Stocks: a fill pays for the move it causes (ADR-126). The next tick moves the price by the player impact
  -- (0.01 x value / depthCentsPer100Bps); the fill pays half of that on average, so buying and selling right away
  -- can never earn the move one causes oneself.
  if s.kind = 'stock' then
    v_a := greatest(v_a, 0.01 * (v_touch / 100.0)
                         / greatest(1, public.cfg_num(v_trading,
                                         array['playerImpact', 'depthCentsPer100Bps',
                                               coalesce((select c.tier::text from public.companies c where c.id = s.company_id), 'midcap')],
                                         2500000)));
  end if;

  -- quantity from the amount (neo-broker semantics) ------------------------------
  if p_amount_cents is not null then
    if v_side = 'buy' then
      -- the player pays at most the amount including the fee
      v_net_amount := p_amount_cents - v_fee;
      if v_net_amount < v_min_value then
        perform public.api_error('order_too_small');
      end if;
      if v_type = 'limit' then
        v_qty := floor(v_net_amount * 100000000.0 / v_limit)::bigint;
      else
        v_qty := floor(v_net_amount * 100000000.0 / v_touch)::bigint;
        -- price of that quantity (>= the price of the final, slightly smaller quantity)
        v_fill_price := round(v_touch * (1 + v_a * (v_pos + v_qty / v_scale / 2)))::bigint;
        v_qty := floor(v_net_amount * 100000000.0 / v_fill_price)::bigint;
      end if;
    else
      -- the amount is the gross proceeds before fee and tax
      if p_amount_cents < v_min_value then
        perform public.api_error('order_too_small');
      end if;
      if v_type = 'limit' then
        v_qty := ceil(p_amount_cents * 100000000.0 / v_limit)::bigint;
      else
        v_qty := ceil(p_amount_cents * 100000000.0 / v_touch)::bigint;
        v_fill_price := greatest(v_min_price, round(v_touch * (1 - v_a * (v_pos + v_qty / v_scale / 2)))::bigint);
        v_qty := ceil(p_amount_cents * 100000000.0 / v_fill_price)::bigint;
      end if;
    end if;
  else
    v_qty := p_quantity_e6;
  end if;

  if v_qty < 1 then
    perform public.api_error('order_too_small');
  end if;
  if v_qty > public.cfg_num(v_trading, '{maxOrderQuantity}', 100000) * v_scale then
    perform public.api_error('invalid_quantity');
  end if;

  -- sells: free position; >= 99.9 % of it is rounded up to the whole position
  if v_side = 'sell' then
    select p.quantity_e6 - p.reserved_quantity_e6 into v_avail
      from public.positions p
     where p.player_id = v_player and p.security_id = s.id and p.side = 'long' and p.leverage = 1 and p.status = 'open'
       for update;
    v_avail := coalesce(v_avail, 0);
    if v_qty < v_avail and v_qty * 1000 >= v_avail * 999 then
      v_qty := v_avail;
    end if;
    if v_avail < v_qty then
      perform public.api_error('insufficient_position');
    end if;
  end if;

  -- minimum order value at the price it would execute or rest at
  if public.value_cents(v_qty, coalesce(v_limit, v_touch)) < v_min_value
     and not (v_side = 'sell' and v_qty = v_avail) then
    perform public.api_error('order_too_small');
  end if;

  -- how much executes now ---------------------------------------------------------
  if v_type = 'market' then
    v_fill_qty := v_qty;
  elsif v_side = 'buy' and v_touch <= v_limit then
    if v_touch * (1 + v_a * (v_pos + v_qty / v_scale)) <= v_limit then
      v_fill_qty := v_qty;
    else
      v_fill_qty := greatest(0, least(v_qty, floor(((v_limit::double precision / v_touch - 1) / v_a - v_pos) * v_scale)::bigint));
    end if;
  elsif v_side = 'sell' and v_touch >= v_limit then
    if v_touch * (1 - v_a * (v_pos + v_qty / v_scale)) >= v_limit then
      v_fill_qty := v_qty;
    else
      v_fill_qty := greatest(0, least(v_qty, floor(((1 - v_limit::double precision / v_touch) / v_a - v_pos) * v_scale)::bigint));
    end if;
  end if;

  if v_fill_qty > 0 then
    if v_side = 'buy' then
      if not (p_amount_cents is not null and v_type = 'market') then
        v_fill_price := round(v_touch * (1 + v_a * (v_pos + v_fill_qty / v_scale / 2)))::bigint;
      end if;
      if v_type = 'limit' then
        v_fill_price := least(v_fill_price, v_limit);
      end if;
    else
      if not (p_amount_cents is not null and v_type = 'market') then
        v_fill_price := greatest(v_min_price, round(v_touch * (1 - v_a * (v_pos + v_fill_qty / v_scale / 2)))::bigint);
      end if;
      if v_type = 'limit' then
        v_fill_price := greatest(v_fill_price, v_limit);
      end if;
    end if;
  end if;
  v_rest := v_qty - v_fill_qty;

  if v_side = 'buy' then
    v_need := 0;
    if v_fill_qty > 0 then
      v_need := public.value_cents(v_fill_qty, v_fill_price) + v_fee;
    end if;
    if v_rest > 0 then
      v_need := v_need + public.value_cents(v_rest, v_limit) + case when v_fill_qty > 0 then 0 else v_fee end;
    end if;
    if v_need > v_cash then
      perform public.api_error('insufficient_funds');
    end if;
  end if;

  -- order, fill, reservation ---------------------------------------------------------
  insert into public.orders (id, player_id, security_id, request_id, side, type, quantity_e6, limit_price_e4, status)
  values (v_order_id, v_player, s.id, p_request_id, v_side, v_type, v_qty, v_limit, 'pending');

  if v_fill_qty > 0 then
    v_fill := public.execute_fill(v_order_id, v_fill_qty, v_fill_price, false, false);
  end if;

  if v_rest > 0 then
    select * into o from public.orders where id = v_order_id;
    if v_side = 'buy' then
      v_reserve := public.value_cents(v_rest, v_limit) + case when o.fee_cents = 0 then v_fee else 0 end;
      if v_reserve > 0 then
        perform public.ledger_transfer(
          public.ledger_player_account(v_player, 'player_cash'),
          public.ledger_player_account(v_player, 'player_reserve'),
          v_reserve, 'order_reserve', 'Reservierung Limit-Order', 'order', v_order_id,
          'reserve:' || v_order_id::text, v_player);
      end if;
      update public.orders set reserved_cents = v_reserve where id = v_order_id;
    else
      update public.positions p
         set reserved_quantity_e6 = p.reserved_quantity_e6 + v_rest
       where p.player_id = v_player and p.security_id = s.id and p.side = 'long' and p.leverage = 1 and p.status = 'open';
      update public.orders set reserved_quantity_e6 = v_rest where id = v_order_id;
    end if;
    update public.orders
       set status = case when v_fill_qty > 0 then 'partially_filled'::public.order_status else 'open'::public.order_status end
     where id = v_order_id;
  end if;
  if v_type = 'limit' then
    perform public.mission_event(v_player, 'limit_order', 1, null);
  end if;

  select * into o from public.orders where id = v_order_id;
  select * into v_prof from public.profiles where id = v_player;
  return public.request_complete(v_player, p_request_id, jsonb_build_object(
    'order_id',           o.id,
    'status',             o.status,
    'quantity_e6',        o.quantity_e6,
    'filled_quantity_e6', o.filled_quantity_e6,
    'avg_price_e4',       o.avg_fill_price_e4,
    'gross_cents',        coalesce((v_fill ->> 'gross_cents')::bigint, 0),
    'fee_cents',          o.fee_cents,
    'tax_cents',          coalesce((v_fill ->> 'tax_cents')::bigint, 0),
    'realized_pnl_cents', (v_fill ->> 'realized_pnl_cents')::bigint,
    'cash_cents',         (select a.balance_cents from public.ledger_accounts a where a.owner_player_id = v_player and a.kind = 'player_cash'),
    'reserved_cents',     o.reserved_cents,
    'xp_awarded',         coalesce((v_fill ->> 'xp_awarded')::integer, 0),
    'level',              v_prof.level,
    'xp_total',           v_prof.xp_total,
    'ticker',             s.ticker,
    'side',               o.side,
    'type',               o.type,
    'limit_price_e4',     o.limit_price_e4,
    'amount_cents',       p_amount_cents));
end;
$$;

-- ===== supabase/updates/20261203001500_company_moves.sql =====
-- ===== idempotent copy of migrations/20261203001500_company_moves.sql =====
-- (the migration itself is written idempotently; keep both files identical below this line)
-- =============================================================================
-- NEXA · 1500 · Business moves: many active ways to earn with a company (ADR-127)
-- =============================================================================
-- Every player company gets a choice of moves that fit its product (game_config.companyMoves.moves; product "*" =
-- every company): a cost from the company cash, a duration, a chance and a result. Cash moves pay back the cost with
-- profit on success (part of it on failure); awareness and quality moves make the company better for good. Skills
-- of the move's area in the team raise the chance. Moves run in slots by company tier and rest a while afterwards.
-- Money: cost to the households (company_costs), payouts from the households (company_revenue); closed system.
-- Contract work ("Auftragsarbeit") is no longer a choice: free capacity is always sold.
--
-- Table company_moves (RLS, no client rights). RPCs (authenticated):
--   get_company_moves() -> COMPANY_MOVES of the player's own company
--   start_company_move(p_request_id uuid, p_key text) -> COMPANY_MOVES
--   COMPANY_MOVES = {"slots", "used", "cash_cents", "tier", "product",
--                    "moves": [{"key","kind","risk","branch","minutes","cost_cents","chance_bps","skill_bonus_bps",
--                               "payout_cents","refund_cents","gain","available_at"}],
--                    "running": [{"id","key","started_at","ends_at","cost_cents","chance_bps"}],
--                    "history": [{"id","key","status","cost_cents","payout_cents","gain","resolved_at"}]}
-- Internal: company_moves_run_due(p_now) (cron nexa-company-moves, every minute).
-- Errors: move_unknown NX107, move_busy NX108, move_resting NX109, plus insufficient_funds, forbidden.
-- Idempotent: runs unchanged as supabase/updates/20261203001500_company_moves.sql.

create table if not exists public.company_moves (
  id            bigint generated always as identity primary key,
  company_id    uuid not null references public.companies (id) on delete cascade,
  move_key      text not null,
  started_by    uuid references public.profiles (id) on delete set null,
  started_at    timestamptz not null default now(),
  ends_at       timestamptz not null,
  cost_cents    bigint not null check (cost_cents > 0),
  chance_bps    integer not null check (chance_bps between 0 and 10000),
  status        text not null default 'running' check (status in ('running', 'success', 'failure')),
  payout_cents  bigint not null default 0 check (payout_cents >= 0),
  gain          double precision not null default 0,
  resolved_at   timestamptz
);
alter table public.company_moves enable row level security;
revoke all on public.company_moves from public, anon, authenticated;
create index if not exists company_moves_company_idx on public.company_moves (company_id, started_at desc);
create index if not exists company_moves_due_idx on public.company_moves (ends_at) where status = 'running';
create index if not exists company_moves_started_by_idx on public.company_moves (started_by);
comment on table public.company_moves is 'Business moves of player companies (ADR-127). Internal; read through get_company_moves().';

-- error keys (as in the friend code migration plus the moves)
do $$
declare
  v_def text;
begin
  v_def := pg_get_functiondef('public.api_error(text)'::regprocedure);
  if position('move_unknown' in v_def) = 0 then
    v_def := replace(v_def, $q$    when 'friend_code_used'            then 'NX106'
$q$, $q$    when 'friend_code_used'            then 'NX106'
    when 'move_unknown'                then 'NX107'
    when 'move_busy'                   then 'NX108'
    when 'move_resting'                then 'NX109'
$q$);
    if position('move_unknown' in v_def) = 0 then
      raise exception 'api_error() has an unexpected shape; add the move error keys by hand';
    end if;
    execute v_def;
  end if;
end;
$$;

-- contract work is always on (ADR-127)
alter table public.player_companies alter column contract_work set default true;
update public.player_companies set contract_work = true where not contract_work;

create or replace function public.company_moves_cfg()
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(public.config_jsonb('companyMoves'), '{}'::jsonb);
$$;

-- skills of an area in the team of a company (founder and employees)
create or replace function public.company_move_skill_count(p_company uuid, p_branch text)
returns integer
language sql
stable
security definer
set search_path = ''
as $$
  select count(*)::integer from public.company_team_skills(p_company) t
   where t.skill_key like p_branch || '\_%' or (t.skill_key like 'hybrid\_%' and exists (
           select 1 from jsonb_array_elements(coalesce(public.config_jsonb('skills', '{tree}'), '[]'::jsonb)) n
            where n ->> 'key' = t.skill_key and n -> 'branches' ? p_branch));
$$;

-- the moves of a company with their current numbers
create or replace function public.company_moves_state(p_company uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_cfg   jsonb := public.company_moves_cfg();
  pc      public.player_companies;
  v_tier  text;
  v_base  bigint;
  v_slots integer;
  v_now   timestamptz := public.game_now();
  v_cash  bigint;
begin
  select * into pc from public.player_companies where company_id = p_company;
  v_tier := case when pc.tier in ('garage', 'small_business', 'gmbh', 'ag') then pc.tier else 'ag' end;
  v_base := coalesce((v_cfg #>> array['costCentsByTier', v_tier])::bigint, 100000);
  v_slots := coalesce((v_cfg #>> array['slotsByTier', v_tier])::integer, 1);
  select a.balance_cents into v_cash from public.ledger_accounts a where a.id = public.company_cash_account(p_company);
  return jsonb_build_object(
    'slots', v_slots,
    'used', (select count(*) from public.company_moves m where m.company_id = p_company and m.status = 'running'),
    'cash_cents', coalesce(v_cash, 0),
    'tier', v_tier,
    'product', pc.product_key,
    'moves', coalesce((
      select jsonb_agg(x.j order by x.ord) from (
        select o.ord, jsonb_build_object(
                 'key', mv ->> 'key', 'kind', mv ->> 'kind', 'risk', mv ->> 'risk', 'branch', mv ->> 'branch',
                 'minutes', (mv ->> 'minutes')::integer,
                 'cost_cents', round(v_base * (mv ->> 'costFactor')::numeric)::bigint,
                 'chance_bps', least(coalesce((v_cfg ->> 'maxChanceBps')::integer, 9500),
                                     (v_cfg #>> array['risk', mv ->> 'risk', 'chanceBps'])::integer + sb.bonus),
                 'skill_bonus_bps', sb.bonus,
                 'payout_cents', case when mv ->> 'kind' = 'cash'
                                      then round(v_base * (mv ->> 'costFactor')::numeric
                                                 * (v_cfg #>> array['risk', mv ->> 'risk', 'payoutBps'])::numeric / 10000)::bigint
                                      else 0 end,
                 'refund_cents', round(v_base * (mv ->> 'costFactor')::numeric
                                       * (v_cfg #>> array['risk', mv ->> 'risk', 'refundBps'])::numeric / 10000)::bigint,
                 'gain', case when mv ->> 'kind' = 'cash' then 0
                              else (v_cfg #>> array['risk', mv ->> 'risk', 'gain'])::double precision end,
                 'available_at', (select max(m.started_at + make_interval(mins => ((mv ->> 'minutes')::integer
                                         * (1 + coalesce((v_cfg ->> 'cooldownFactor')::integer, 2)))))
                                    from public.company_moves m where m.company_id = p_company and m.move_key = mv ->> 'key'
                                     and m.started_at + make_interval(mins => ((mv ->> 'minutes')::integer
                                         * (1 + coalesce((v_cfg ->> 'cooldownFactor')::integer, 2)))) > v_now)) as j
          from jsonb_array_elements(coalesce(v_cfg -> 'moves', '[]'::jsonb)) with ordinality o(mv, ord)
          cross join lateral (select least(coalesce((v_cfg ->> 'maxSkillBonusBps')::integer, 2500),
                                           coalesce((v_cfg ->> 'chancePerSkillBps')::integer, 300)
                                           * public.company_move_skill_count(p_company, o.mv ->> 'branch')) as bonus) sb
         where o.mv ->> 'product' in ('*', coalesce(pc.product_key, ''))) x), '[]'::jsonb),
    'running', coalesce((
      select jsonb_agg(jsonb_build_object('id', m.id, 'key', m.move_key, 'started_at', m.started_at, 'ends_at', m.ends_at,
                                          'cost_cents', m.cost_cents, 'chance_bps', m.chance_bps) order by m.ends_at)
        from public.company_moves m where m.company_id = p_company and m.status = 'running'), '[]'::jsonb),
    'history', coalesce((
      select jsonb_agg(jsonb_build_object('id', h.id, 'key', h.move_key, 'status', h.status, 'cost_cents', h.cost_cents,
                                          'payout_cents', h.payout_cents, 'gain', h.gain, 'resolved_at', h.resolved_at)
                       order by h.resolved_at desc, h.id desc)
        from (select m.* from public.company_moves m where m.company_id = p_company and m.status <> 'running'
               order by m.resolved_at desc, m.id desc limit coalesce((v_cfg ->> 'historyLimit')::integer, 12)) h), '[]'::jsonb));
end;
$$;

create or replace function public.get_company_moves()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_player  uuid := public.require_player();
  v_company uuid;
begin
  select pc.company_id into v_company from public.player_companies pc
   where pc.founder_id = v_player and pc.status = 'active';
  if v_company is null then
    perform public.api_error('company_not_found');
  end if;
  return public.company_moves_state(v_company);
end;
$$;
comment on function public.get_company_moves() is 'RPC: the business moves of the own company (ADR-127).';

create or replace function public.start_company_move(p_request_id uuid, p_key text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player  uuid;
  v_replay  jsonb;
  pc        public.player_companies;
  v_state   jsonb;
  v_move    jsonb;
  v_cash    bigint;
  v_cost    bigint;
begin
  v_player := public.require_player();
  if p_request_id is null or p_key is null then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'start_company_move');
  if v_replay is not null then
    return v_replay;
  end if;
  select * into pc from public.player_companies where founder_id = v_player and status = 'active' for update;
  if pc.company_id is null then
    perform public.api_error('company_not_found');
  end if;
  v_state := public.company_moves_state(pc.company_id);
  select m into v_move from jsonb_array_elements(v_state -> 'moves') m where m ->> 'key' = p_key;
  if v_move is null then
    perform public.api_error('move_unknown');
  end if;
  if (v_state ->> 'used')::integer >= (v_state ->> 'slots')::integer then
    perform public.api_error('move_busy');
  end if;
  if v_move ->> 'available_at' is not null and (v_move ->> 'available_at')::timestamptz > public.game_now() then
    perform public.api_error('move_resting');
  end if;
  v_cost := (v_move ->> 'cost_cents')::bigint;
  select a.balance_cents into v_cash from public.ledger_accounts a
   where a.id = public.company_cash_account(pc.company_id) for update;
  if coalesce(v_cash, 0) < v_cost then
    perform public.api_error('insufficient_funds');
  end if;
  perform public.ledger_transfer(public.company_cash_account(pc.company_id), public.ledger_system_account('households'),
                                 v_cost, 'company_costs', 'Geschäftszug: ' || p_key, 'company', pc.company_id,
                                 'move:start:' || p_request_id::text, v_player, jsonb_build_object('move', p_key));
  insert into public.company_moves (company_id, move_key, started_by, started_at, ends_at, cost_cents, chance_bps)
  values (pc.company_id, p_key, v_player, public.game_now(),
          public.game_now() + make_interval(mins => (v_move ->> 'minutes')::integer), v_cost, (v_move ->> 'chance_bps')::integer);
  return public.request_complete(v_player, p_request_id, public.company_moves_state(pc.company_id));
end;
$$;
comment on function public.start_company_move(uuid, text) is 'RPC: the founder starts a business move of the own company (ADR-127).';

create or replace function public.company_moves_run_due(p_now timestamptz default null)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_cfg     jsonb := public.company_moves_cfg();
  v_now     timestamptz := coalesce(p_now, public.game_now());
  m         record;
  v_kind    text;
  v_risk    text;
  v_ok      boolean;
  v_pay     bigint;
  v_gain    double precision;
  v_hh      uuid := public.ledger_system_account('households');
  v_hh_bal  bigint;
  v_done    integer := 0;
begin
  for m in select x.* from public.company_moves x where x.status = 'running' and x.ends_at <= v_now
            order by x.ends_at, x.id for update skip locked loop
    select mv ->> 'kind', mv ->> 'risk' into v_kind, v_risk
      from jsonb_array_elements(coalesce(v_cfg -> 'moves', '[]'::jsonb)) mv where mv ->> 'key' = m.move_key;
    v_kind := coalesce(v_kind, 'cash');
    v_risk := coalesce(v_risk, 'normal');
    v_ok := random() * 10000 < m.chance_bps;
    v_gain := 0;
    if v_ok and v_kind = 'cash' then
      v_pay := round(m.cost_cents * coalesce((v_cfg #>> array['risk', v_risk, 'payoutBps'])::numeric, 15000) / 10000)::bigint;
    elsif v_ok then
      v_pay := 0;
      v_gain := coalesce((v_cfg #>> array['risk', v_risk, 'gain'])::double precision, 0.04);
    else
      v_pay := round(m.cost_cents * coalesce((v_cfg #>> array['risk', v_risk, 'refundBps'])::numeric, 3000) / 10000)::bigint;
    end if;
    if not exists (select 1 from public.player_companies pc where pc.company_id = m.company_id and pc.status = 'active') then
      v_pay := 0;
      v_gain := 0;
    end if;
    if v_pay > 0 then
      select a.balance_cents into v_hh_bal from public.ledger_accounts a where a.id = v_hh for update;
      v_pay := least(v_pay, greatest(0, coalesce(v_hh_bal, 0)));
    end if;
    if v_pay > 0 then
      perform public.ledger_transfer(v_hh, public.company_cash_account(m.company_id), v_pay, 'company_revenue',
                                     'Geschäftszug: ' || m.move_key, 'company', m.company_id,
                                     'move:result:' || m.id::text, null, jsonb_build_object('move', m.move_key, 'success', v_ok));
    end if;
    if v_gain > 0 then
      if v_kind = 'awareness' then
        update public.player_companies set awareness = least(1, awareness + v_gain) where company_id = m.company_id;
      else
        update public.player_companies set quality = least(1, quality + v_gain) where company_id = m.company_id;
      end if;
    end if;
    update public.company_moves set status = case when v_ok then 'success' else 'failure' end, payout_cents = v_pay,
                                    gain = v_gain, resolved_at = v_now where id = m.id;
    perform public.company_system_message(m.company_id,
      case when v_ok and v_kind = 'cash' then 'Geschäftszug geschafft: ' || public.format_eur(v_pay) || ' eingenommen.'
           when v_ok then 'Geschäftszug geschafft: die Firma ist jetzt '
                          || case when v_kind = 'awareness' then 'bekannter' else 'besser' end || '.'
           else 'Geschäftszug daneben gegangen, ' || public.format_eur(v_pay) || ' zurück.' end);
    v_done := v_done + 1;
  end loop;
  return jsonb_build_object('resolved', v_done);
end;
$$;
comment on function public.company_moves_run_due(timestamptz) is
  'Internal, cron every minute (ADR-127): resolves due business moves (payout, refund or a lasting gain).';

do $$
declare
  f text;
begin
  foreach f in array array['public.company_moves_cfg()', 'public.company_move_skill_count(uuid, text)',
                           'public.company_moves_state(uuid)', 'public.company_moves_run_due(timestamptz)'] loop
    execute format('revoke all on function %s from public, anon, authenticated', f);
    execute format('grant execute on function %s to service_role', f);
  end loop;
  foreach f in array array['public.get_company_moves()', 'public.start_company_move(uuid, text)'] loop
    execute format('revoke all on function %s from public, anon', f);
    execute format('grant execute on function %s to authenticated, service_role', f);
  end loop;
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    if exists (select 1 from cron.job where jobname = 'nexa-company-moves') then
      perform cron.unschedule('nexa-company-moves');
    end if;
    perform cron.schedule('nexa-company-moves', '* * * * *', 'select public.company_moves_run_due()');
  end if;
end;
$$;

commit;
